int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    while (cin >> n) {
        vector<long long> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];

        vector<long long> sorted_a(a);
        sort(sorted_a.begin(), sorted_a.end());

        long long global_min = sorted_a[0];

        // Map value to its target position
        map<long long, queue<int>> pos_map;
        for (int i = 0; i < n; i++) {
            pos_map[sorted_a[i]].push(i);
        }

        vector<int> perm(n);
        for (int i = 0; i < n; i++) {
            perm[i] = pos_map[a[i]].front();
            pos_map[a[i]].pop();
        }

        vector<bool> visited(n, false);
        long long total_cost = 0;

        for (int i = 0; i < n; i++) {
            if (visited[i] || perm[i] == i) {
                visited[i] = true;
                continue;
            }

            // Find cycle
            vector<int> cycle;
            int j = i;
            while (!visited[j]) {
                visited[j] = true;
                cycle.push_back(j);
                j = perm[j];
            }

            int k = cycle.size();
            long long S = 0, cycle_min = LLONG_MAX;
            for (int idx : cycle) {
                S += sorted_a[idx];
                cycle_min = min(cycle_min, sorted_a[idx]);
            }

            // Strategy 1: use cycle's own minimum
            long long cost1 = S + (long long)(k - 2) * cycle_min;

            // Strategy 2: use global minimum
            long long cost2 = S + cycle_min + (long long)(k + 1) * global_min;

            total_cost += min(cost1, cost2);
        }

        cout << total_cost << "\n";
    }

    return 0;
}

