typedef struct {
    int value;
    int index;
} Element;

int compare(const void *a, const void *b) {
    return ((Element*)a)->value - ((Element*)b)->value;
}

int main() {
    int n;
    scanf("%d", &n);

    int *arr = malloc(n * sizeof(int));
    Element *sorted = malloc(n * sizeof(Element));

    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
        sorted[i].value = arr[i];
        sorted[i].index = i;
    }

    qsort(sorted, n, sizeof(Element), compare);

    int *visited = calloc(n, sizeof(int));
    int global_min = sorted[0].value;
    long long total_cost = 0;

    for (int i = 0; i < n; i++) {
        if (visited[i]) continue;

        int cur = i;
        int cycle_len = 0;
        int cycle_min = INT_MAX;
        long long cycle_sum = 0;

        while (!visited[cur]) {
            visited[cur] = 1;
            cycle_len++;
            int val = arr[cur];
            cycle_sum += val;
            if (val < cycle_min) cycle_min = val;
            cur = sorted[cur].index;
        }

        if (cycle_len > 1) {
            long long method1 = cycle_sum + (long long)(cycle_len - 2) * cycle_min;
            long long method2 = cycle_sum + cycle_min + (long long)(cycle_len + 1) * global_min;
            total_cost += (method1 < method2) ? method1 : method2;
        }
    }

    printf("%lld\n", total_cost);

    free(arr);
    free(sorted);
    free(visited);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int cmp(const void *a, const void *b) {
    int *x = (int*)a, *y = (int*)b;
    if (x[0] != y[0]) return x[0] - y[0];
    return x[1] - y[1];
}

int main() {
    int n;
    while (scanf("%d", &n) == 1) {
        int *arr = malloc(n * sizeof(int));
        int (*sorted)[2] = malloc(n * sizeof(*sorted));
        for (int i = 0; i < n; i++) {
            scanf("%d", &arr[i]);
            sorted[i][0] = arr[i];
            sorted[i][1] = i;
        }
        qsort(sorted, n, sizeof(*sorted), cmp);

        // pos[i] = where sorted[i] currently is
        int *pos = malloc(n * sizeof(int));
        int *where = malloc(n * sizeof(int)); // where[i] = which sorted position is at index i
        for (int i = 0; i < n; i++) pos[i] = sorted[i][1];
        // Build inverse
        for (int i = 0; i < n; i++) where[pos[i]] = i;

        int global_min = sorted[0][0];
        int *visited = calloc(n, sizeof(int));
        long long total = 0;

        for (int i = 0; i < n; i++) {
            if (visited[i] || pos[i] == i) { visited[i] = 1; continue; }
            // Find cycle
            int cycle_len = 0, local_min = sorted[i][0];
            long long cycle_sum = 0;
            int j = i;
            while (!visited[j]) {
                visited[j] = 1;
                cycle_sum += sorted[j][0];
                if (sorted[j][0] < local_min) local_min = sorted[j][0];
                cycle_len++;
                j = where[pos[j]]; // next in cycle... 
                // Actually cycle: j -> pos[j] should go to j, so next is where[j] meaning who wants to go to pos[j]
            }
            long long opt1 = cycle_sum + (long long)(cycle_len - 2) * local_min;
            long long opt2 = cycle_sum + local_min + (long long)(cycle_len - 1) * global_min;
            total += (opt1 < opt2) ? opt1 : opt2;
        }
        printf("%lld\n", total);
        free(arr); free(sorted); free(pos); free(where); free(visited);
    }
}

