typedef long long ll;

typedef struct {
    ll val;
    int idx;
} Node;

int cmp_node(const void *a, const void *b) {
    ll x = ((const Node *)a)->val;
    ll y = ((const Node *)b)->val;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    ll *a = (ll *)malloc((size_t)n * sizeof(ll));
    Node *arr = (Node *)malloc((size_t)n * sizeof(Node));
    int *to = (int *)malloc((size_t)n * sizeof(int));
    char *vis = (char *)calloc((size_t)n, sizeof(char));

    ll global_min = (1LL << 60);

    for (int i = 0; i < n; i++) {
        scanf("%lld", &a[i]);
        arr[i].val = a[i];
        arr[i].idx = i;
        if (a[i] < global_min) global_min = a[i];
    }

    qsort(arr, n, sizeof(Node), cmp_node);

    /* to[original_index] = sorted_position */
    for (int i = 0; i < n; i++) {
        to[arr[i].idx] = i;
    }

    ll ans = 0;

    for (int i = 0; i < n; i++) {
        if (vis[i] || to[i] == i) continue;

        int cur = i;
        int cnt = 0;
        ll sum = 0;
        ll cycle_min = (1LL << 60);

        while (!vis[cur]) {
            vis[cur] = 1;
            ll v = a[cur];
            sum += v;
            if (v < cycle_min) cycle_min = v;
            cnt++;
            cur = to[cur];
        }

        /* Two ways to resolve a cycle:
           1) Use only elements in the cycle:
              cost = sum + (cnt - 2) * cycle_min
           2) Use the global minimum as helper:
              cost = sum + cycle_min + (cnt + 1) * global_min
        */
        ll cost1 = sum + (ll)(cnt - 2) * cycle_min;
        ll cost2 = sum + cycle_min + (ll)(cnt + 1) * global_min;

        ans += (cost1 < cost2 ? cost1 : cost2);
    }

    printf("%lld\n", ans);

    free(a);
    free(arr);
    free(to);
    free(vis);
    return 0;
}

