import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Pair {
        long value;
        int index;

        Pair(long value, int index) {
            this.value = value;
            this.index = index;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        long[] a = new long[n];
        Pair[] arr = new Pair[n];
        long globalMin = Long.MAX_VALUE;

        for (int i = 0; i < n; i++) {
            a[i] = fs.nextLong();
            arr[i] = new Pair(a[i], i);
            globalMin = Math.min(globalMin, a[i]);
        }

        Arrays.sort(arr, Comparator.comparingLong(p -> p.value));

        int[] to = new int[n];
        for (int sortedPos = 0; sortedPos < n; sortedPos++) {
            to[arr[sortedPos].index] = sortedPos;
        }

        boolean[] visited = new boolean[n];
        long answer = 0;

        for (int i = 0; i < n; i++) {
            if (visited[i]) continue;

            int cur = i;
            int cycleSize = 0;
            long cycleSum = 0;
            long cycleMin = Long.MAX_VALUE;

            while (!visited[cur]) {
                visited[cur] = true;
                long v = a[cur];
                cycleSum += v;
                cycleMin = Math.min(cycleMin, v);
                cycleSize++;
                cur = to[cur];
            }

            if (cycleSize <= 1) continue;

            long method1 = cycleSum + (long) (cycleSize - 2) * cycleMin;
            long method2 = cycleSum + cycleMin + (long) (cycleSize + 1) * globalMin;

            answer += Math.min(method1, method2);
        }

        System.out.println(answer);
    }
